var QUOTE_TD_VM1_RD = "5dbbc58255f3e0312c60973e9283dc8376387e598e05f91c8b62c549ab615ab39ac5c2874e22d13bcca32888f4413a1d4160f8e353afe2a2f11ae73e3cd54e1b"

func TestVerification_Verify_TDVM(t *testing.T) {
	quoteVerifier := NewTdxQuoteVerifier()
	quote, err := base64.StdEncoding.DecodeString(QUOTE_TD_VM1)
	if err != nil {
		log.Fatal(err)
	}
	_, err = quoteVerifier.Verify(quote)
	if err != nil {
		log.Fatal(err)
	}
}

func hexStr(label string, b []byte) string {
	if len(b) == 0 {
		return fmt.Sprintf("%s: <empty>", label)
	}
	return fmt.Sprintf("%s: %s", label, hex.EncodeToString(b))
}

func hexStrList(label string, list [][]byte) string {
	if len(list) == 0 {
		return fmt.Sprintf("%s: <empty>", label)
	}
	var parts []string
	for i, b := range list {
		parts = append(parts, fmt.Sprintf("%s[%d]: %s", label, i, hex.EncodeToString(b)))
	}
	return strings.Join(parts, "\n")
}

func TestQuote_Parse_TDVM(t *testing.T) {
	quoteVerifier := NewTdxQuoteVerifier()
	quote, err := base64.StdEncoding.DecodeString(QUOTE_TD_VM1)
	if err != nil {
		log.Fatal(err)
	}
	quoteV4, err := quoteVerifier.Parse(quote)

	if err != nil {
		log.Fatal(err)
	}
	assert.Equal(t, hex.EncodeToString(quoteV4.TdQuoteBody.GetReportData()), QUOTE_TD_VM1_RD, "Report Data do not match")
	// log.Printf("* Quote V4: %v", quoteV4)
	// log.Printf("%v", quoteV4.TdQuoteBody.String())
	header := quoteV4.Header

	fmt.Println("=== Quote Header ===")
	fmt.Printf("Version: %d\n", header.Version)
	fmt.Printf("Attestation Key Type: %d\n", header.AttestationKeyType)
	fmt.Printf("TEE Type: 0x%X\n", header.TeeType)
	fmt.Printf("QE SVN: %s\n", hex.EncodeToString(header.QeSvn))
	fmt.Printf("PCE SVN: %s\n", hex.EncodeToString(header.PceSvn))
	fmt.Printf("QE Vendor ID: %s\n", hex.EncodeToString(header.QeVendorId))
	fmt.Printf("User Data: %s\n", hex.EncodeToString(header.UserData))
	tdBody := quoteV4.TdQuoteBody
	fmt.Println("=== TD Quote Body ===")
	fmt.Println(hexStr("TeeTcbSvn", tdBody.TeeTcbSvn))
	fmt.Println(hexStr("MrSeam", tdBody.MrSeam))
	fmt.Println(hexStr("MrSignerSeam", tdBody.MrSignerSeam))
	fmt.Println(hexStr("SeamAttributes", tdBody.SeamAttributes))
	fmt.Println(hexStr("TdAttributes", tdBody.TdAttributes))
	fmt.Println(hexStr("Xfam", tdBody.Xfam))
	fmt.Println(hexStr("MrTd", tdBody.MrTd))
	fmt.Println(hexStr("MrConfigId", tdBody.MrConfigId))
	fmt.Println(hexStr("MrOwner", tdBody.MrOwner))
	fmt.Println(hexStr("MrOwnerConfig", tdBody.MrOwnerConfig))
	fmt.Println(hexStrList("RTMR", tdBody.Rtmrs))
	fmt.Println(hexStr("ReportData", tdBody.ReportData))
	// log.Println(quoteV4.TdQuoteBody.GetReportData())
}
